<script>
 import {user,notify} from '$lib/stores.js';
 import {changePassword,rotateAgentToken,listAPIKeys,createAPIKey,revokeAPIKey} from '$lib/api.js';
 import Button from '$lib/components/Button.svelte';
 let copied=false;
 let agentToken='',agentTokenBusy=false;
 let currentPassword='',newPassword='',confirmPassword='',passwordBusy=false;
 let apiKeys=[],apiKeysLoaded=false,apiKeyName='Personal integration',apiKeyBusy=false,apiKeyOnce='';
 $: canUseAPI=$user && (($user.status==='pro' || $user.status==='advanced') || $user.is_admin);
 $: if(canUseAPI && !apiKeysLoaded) loadAPIKeys();
 async function loadAPIKeys(){apiKeysLoaded=true;const r=await listAPIKeys();if(r.ok)apiKeys=r.data?.keys||[];else notify(r.error||'Не удалось загрузить API keys','error')}
 async function addAPIKey(){apiKeyBusy=true;apiKeyOnce='';const r=await createAPIKey(apiKeyName);apiKeyBusy=false;if(r.ok){apiKeyOnce=r.data?.key||'';await loadAPIKeys();notify('API key создан. Скопируйте его сейчас.','success')}else notify(r.error||'Не удалось создать API key','error')}
 async function removeAPIKey(id){const r=await revokeAPIKey(id);if(r.ok){apiKeys=apiKeys.filter(k=>k.id!==id);notify('API key отозван','success')}else notify(r.error||'Не удалось отозвать API key','error')}
 $: referralLink=typeof window!=='undefined'&&$user?window.location.origin+'/register?ref='+$user.referral_code:'';
 async function copy(value){try{await navigator.clipboard.writeText(value);copied=true;notify('Скопировано','success');setTimeout(()=>copied=false,1800)}catch{notify('Не удалось скопировать','error')}}
 function statusLabel(s){return s==='free'?'Free':s==='pro'?'Pro':s==='advanced'?'Advanced':s==='commercial'?'Commercial':s==='blocked'?'Blocked':s}
 async function createAgentToken(){
  agentTokenBusy=true;agentToken='';
  const result=await rotateAgentToken();
  agentTokenBusy=false;
  if(result.ok){agentToken=result.data?.token||'';notify('Новый pairing token создан. Старый токен отозван.','success')}
  else notify(result.error||'Не удалось создать pairing token','error');
 }
 async function submitPassword(){
  if(newPassword!==confirmPassword){notify('Новые пароли не совпадают','error');return}
  if(newPassword.length<12){notify('Новый пароль должен содержать минимум 12 символов','error');return}
  passwordBusy=true;
  const result=await changePassword(currentPassword,newPassword);
  passwordBusy=false;
  if(result.ok){currentPassword='';newPassword='';confirmPassword='';notify('Пароль изменён. Остальные сессии завершены.','success')}
  else notify(result.error||'Не удалось изменить пароль','error');
 }
</script>
<div class="page-header"><div><div class="eyebrow">ACCOUNT</div><h1 class="page-title">Профиль</h1><p class="page-desc">Данные аккаунта, безопасность и реферальная программа.</p></div></div>
{#if $user}
<section class="panel"><h2>Account details</h2><div class="details"><div><small>Username</small><strong>{$user.username}</strong></div><div><small>Email</small><strong>{$user.email}</strong></div><div><small>Plan status</small><strong>{$user.is_admin?"Administrator":statusLabel($user.status)}</strong></div><div><small>Device limit</small><strong>{canUseAPI?"Без ограничений":$user.max_devices+$user.bonus_devices}</strong></div></div></section>
<section class="panel plans-panel">
 <div class="plans-heading"><div><h2>Подписки Yevqo</h2><p>Выбери уровень возможностей платформы. Все цены указаны за месяц.</p></div><span class="current-plan">Текущий план: {$user.is_admin?'Administrator':statusLabel($user.status)}</span></div>
 <div class="plan-grid">
  <article class:plan-active={$user.status==='free'} class="plan-card"><div class="plan-name">Free</div><div class="plan-price">€0 <small>/ месяц</small></div><ul><li>1 подключённое Android-устройство</li><li>Основные функции проектов и деплоя</li><li>Управление собственным устройством</li></ul></article>
  <article class:plan-active={$user.status==='pro'} class="plan-card"><div class="plan-name">Pro</div><div class="plan-price">€5,99 <small>/ месяц</small></div><ul><li>Безлимитное подключение Android Agent</li><li>Yevqo REST API и API keys</li><li>Все возможности Free</li></ul></article>
  <article class:plan-active={$user.status==='advanced'} class="plan-card"><div class="plan-name">Advanced</div><div class="plan-price">€10,99 <small>/ месяц</small></div><ul><li>Всё из Pro</li><li>Agent Network и расширенное управление</li><li>Расширенная аналитика и автоматизация</li><li>Дополнительные security-возможности и лимиты</li></ul><span class="plan-note">Расширенные функции включаются по мере готовности модулей</span></article>
 </div>
 <p class="billing-note">Автоматическая оплата и самостоятельная активация пока не подключены. Сейчас тариф назначается администратором Yevqo.</p>
</section>
{#if canUseAPI}
<section class="panel"><h2>Yevqo Pro REST API</h2><p>Управляйте проектами, устройствами, приложениями, базами данных, резервными копиями, доменами, мониторингом и журналами через HTTPS API. Ключи имеют полный доступ в рамках прав вашего аккаунта.</p><label>Название ключа</label><div class="copy-row"><input bind:value={apiKeyName} maxlength="64" placeholder="CI / Personal integration"/><Button variant="primary" loading={apiKeyBusy} on:click={addAPIKey}>Создать API key</Button></div>{#if apiKeyOnce}<label>Новый ключ — отображается один раз</label><div class="copy-row"><input readonly value={apiKeyOnce}/><Button on:click={()=>copy(apiKeyOnce)}>Копировать</Button></div><small class="token-warning">Сохраните ключ сейчас. В базе хранится только его SHA-256 хеш.</small>{/if}<div class="api-key-list">{#each apiKeys as key}<div class="api-key-row"><div><strong>{key.name}</strong><small>{key.prefix}… · создан {new Date(key.created_at).toLocaleDateString()}</small></div><Button variant="danger" on:click={()=>removeAPIKey(key.id)}>Отозвать</Button></div>{/each}{#if apiKeysLoaded && apiKeys.length===0}<small>Активных ключей пока нет.</small>{/if}</div><p class="api-example">Authorization: Bearer YOUR_API_KEY<br/>GET /v1/projects</p></section>
{/if}
<section class="panel"><h2>Сменить пароль</h2><p>Для подтверждения введите текущий пароль. Новый пароль должен содержать не менее 12 символов. После смены остальные активные сессии будут завершены.</p><form class="password-form" on:submit|preventDefault={submitPassword}><label for="current-password">Текущий пароль</label><input id="current-password" type="password" autocomplete="current-password" bind:value={currentPassword} required/><label for="new-password">Новый пароль</label><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="72" bind:value={newPassword} required/><label for="confirm-password">Повторите новый пароль</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="12" maxlength="72" bind:value={confirmPassword} required/><div class="form-actions"><Button variant="primary" type="submit" loading={passwordBusy}>Сохранить пароль</Button></div></form></section>
<section class="panel"><h2>Referral program</h2><p>Поделитесь ссылкой-приглашением. Реферальные бонусы отображаются в вашем аккаунте.</p><label>Referral link</label><div class="copy-row"><input readonly value={referralLink}/><Button variant="primary" on:click={()=>copy(referralLink)}>{copied?'Скопировано':'Копировать'}</Button></div><label>Agent pairing token</label><p>Это отдельный секрет для подключения устройства. Он не является реферальным кодом. При выпуске нового токена предыдущий сразу перестаёт работать.</p><div class="form-actions"><Button variant="primary" loading={agentTokenBusy} on:click={createAgentToken}>Создать / перевыпустить token</Button></div>{#if agentToken}<div class="copy-row"><input readonly value={agentToken}/><Button on:click={()=>copy(agentToken)}>Копировать</Button></div><small class="token-warning">Показывается только сейчас. Сохраните его в настройке Agent.</small>{/if}</section>
{/if}
<style>
.eyebrow{font-size:9px;font-weight:700;letter-spacing:.14em;color:#8AB4FF;margin-bottom:7px}.panel{background:var(--bg-card);border:1px solid var(--border);border-radius:12px;padding:18px;margin-bottom:13px}.panel h2{font-size:12px;margin-bottom:15px}.panel p{font-size:10px;color:var(--text-muted);margin-bottom:15px;line-height:1.6}.details{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.details div{display:flex;flex-direction:column;gap:4px}.details small,label{font-size:9px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.08em}.details strong{font-size:11px;font-weight:550}.details em{font-size:9px;color:var(--text-dim);font-style:normal}
.plans-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap}.current-plan{font-size:9px;color:var(--text-muted);padding:6px 9px;border:1px solid var(--border);border-radius:7px}.plan-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.plan-card{min-width:0;padding:14px;border:1px solid var(--border);border-radius:9px;background:var(--bg-input)}.plan-card.plan-active{border-color:var(--accent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 25%,transparent)}.plan-name{font-size:11px;font-weight:700}.plan-price{font-size:20px;font-weight:700;margin:9px 0}.plan-price small{font-size:9px;font-weight:400;color:var(--text-muted)}.plan-card ul{padding-left:15px;margin:0;display:grid;gap:7px}.plan-card li{font-size:9px;color:var(--text-muted);line-height:1.45}.plan-note,.billing-note{display:block;font-size:9px;color:var(--text-muted);line-height:1.5;margin-top:12px}.billing-note{padding:10px;background:var(--bg-input);border-radius:7px}@media(max-width:760px){.plan-grid{grid-template-columns:1fr}}.copy-row{display:flex;gap:8px;margin:6px 0 14px}.copy-row input,.password-form input{min-width:0;flex:1;background:var(--bg-input);border:1px solid var(--border);border-radius:8px;color:var(--text-main);padding:9px 10px;font:10px 'JetBrains Mono',monospace}.password-form{display:grid;gap:8px;max-width:440px}.password-form input{width:100%;font-family:inherit}.api-key-list{display:grid;gap:8px;margin:12px 0}.api-key-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px;border:1px solid var(--border);border-radius:8px}.api-key-row div{display:grid;gap:4px;min-width:0}.api-key-row strong{font-size:10px}.api-key-row small,.api-example{font-size:9px;color:var(--text-muted);overflow-wrap:anywhere}.api-example{padding:10px;background:var(--bg-input);border-radius:8px;font-family:monospace}.token-warning{display:block;color:#fbbf24;font-size:9px;margin-top:-8px}.form-actions{margin-top:7px;display:flex;justify-content:flex-start}@media(max-width:600px){.details{grid-template-columns:1fr}.copy-row{flex-wrap:wrap}.copy-row input{flex-basis:100%}}
</style>